window.kbPageData["views/entry/k-cdd2fe1abf4227f3"] = {"key":"entry/k-cdd2fe1abf4227f3","state":{"route":"entry/k-cdd2fe1abf4227f3"},"node":{"id":"k-cdd2fe1abf4227f3","mode":"k","title":"国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表","type":"事实与事件","domain":"科技","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["innovation"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["科技"],"时间索引":["年度事件或数据"],"来源主题":["重要会议讲话"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表","slug":"ccc4263071af"}],"directorySummary":"考点二十八 国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表\n大会（7 月 8 日）\n向 2025 年度国家最高科学技术奖获得者陈立泉院士、贲德院士颁奖。讲话指出我国正从全球\n科技参与者、贡献者向开拓者、引领者加速转变，成为创新力上升最快的国家之一（综合创新\n能力位居世界第九）；“十五五…","sources":[{"id":"97b1a3978bcadfa6","label":"国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表","topic":"重要会议讲话","category":"时政","text":"考点二十八 国家科学技术奖励大会、两院院士大会、中国科协第十一次全国代表\n大会（7 月 8 日）\n向 2025 年度国家最高科学技术奖获得者陈立泉院士、贲德院士颁奖。讲话指出我国正从全球\n科技参与者、贡献者向开拓者、引领者加速转变，成为创新力上升最快的国家之一（综合创新\n能力位居世界第九）；“十五五”时期是科技强国建设的关键攻坚期，要 2035 年建成科技强\n国。\n人工智能以数据、算力、算法为关键要素，以神经科学、认知科学、计算科学、数学等理论突\n破和学科交叉为基础，以智能前沿技术群体性突破和广泛渗透赋能为标志。\n部署六方面工作：增强科技创新体系化攻关能力；推动科技创新和产业创新深度融合（科技创\n新突出应用导向，产业创新提出科学问题）；优化科教协同育人机制培养青年科技人才；提高\n科技创新投入效能；深化科技评价改革（强化创新能力、质量、实效、贡献导向）；加强科技\n伦理和安全治理。","source":{"doc":"4e539a366dce19555ccf","first":6,"last":6,"page":6,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"innovation","title":"科技创新与科研组织"}],"units":{"k-cdd2fe1abf4227f3":[]}};
